ANIMALS = ['bee', 'frog', 'snake', 'seahorse', 'swan', 'stork', 'beetle', 'finch',
           'badger', 'dove', 'woodpecker', 'monkey', 'dragon', 'ostrich', 'beaver',
           'peafowl', 'rhino', 'bison', 'ant', 'zebra', 'dinosaur', 'vampire',
           'goat', 'pigeon', 'dragonfly', 'fangtooth', 'flamingo', 'king', 'emperor']

PRIMARY_COLORS = {'red', 'green', 'blue'}   # source-domain convention
LEAFY_GREEN = {'spinach'}

# Stated facts (positive atoms) and stated negations
POS0 = {
    ('card', 'bee', 'blue'),
    ('card', 'frog', 'yellow'),
    ('has', 'frog', 'spinach'),
    ('reduced_hours', 'snake'),
}
NEG0 = {
    ('tear', 'bee', 'badger'),
    ('create', 'seahorse', 'vampire'),
}
TARGET = ('capture', 'finch', 'pigeon')
SUBMITTED = 'disproved'


def run(mode):
    """Forward chaining. mode='cwa': a negated antecedent holds unless the atom is derived.
    mode='strict': a negated antecedent holds only if stated or derived as a negation."""
    P = set(POS0)
    N = set(NEG0)

    def lacks(atom):
        return (atom not in P) if mode == 'cwa' else (atom in N)

    while True:
        snap = (frozenset(P), frozenset(N))
        blocked15 = any(('trade', y, 'bison') in P for y in ANIMALS)   # Rule15 > Rule1
        blocked3 = any(('persuade', y, 'rhino') in P for y in ANIMALS)  # Rule3 > Rule22
        if blocked3:
            N.add(('shout', 'swan', 'beaver'))

        # Rule 23: snake works fewer hours -> tears down castle of dove
        if ('reduced_hours', 'snake') in P:
            P.add(('tear', 'snake', 'dove'))
        # Rule 2
        if any(('tear', x, 'dove') in P for x in ANIMALS):
            P.add(('emperor', 'woodpecker', 'monkey'))
        # Rule 7 (uses Rule 1 output)
        if any(('unite', x, 'ostrich') in P for x in ANIMALS):
            P.add(('trade', 'beetle', 'stork'))
        # Rule 10
        if any(('wants', y, 'goat') in P for y in ANIMALS):
            N.add(TARGET)
        # Rule 13 (Rule 8 overrides via positive-wins cleanup)
        if any(('emperor', x, 'monkey') in P for x in ANIMALS):
            N.add(('refuse', 'bee', 'dinosaur'))
        # Rule 9
        if ('smile', 'flamingo', 'bee') in P:
            P.add(('shout', 'bee', 'beetle'))
        # Rule 16 / Rule 21 / Rule 11 (age not stated, so Rule 11 is inapplicable)
        for (p, s, c) in list(P):
            if p == 'card' and s == 'frog' and c in PRIMARY_COLORS:
                N.add(('destroy', 'frog', 'swan'))
        for (p, s, o) in list(P):
            if p == 'has' and s == 'frog' and o in LEAFY_GREEN:
                P.add(('destroy', 'frog', 'swan'))
        # Rule 24
        if ('destroy', 'frog', 'swan') in P:
            P.add(('shout', 'swan', 'peafowl'))
        # Rule 6 (blocked by Rule 24 via positive-wins cleanup)
        if any(('enjoy', y, 'ant') in P for y in ANIMALS):
            N.add(('shout', 'swan', 'peafowl'))

        for x in ANIMALS:
            # Rule 1 (blocked by Rule 15 if a bison trade exists)
            if ('shout', x, 'beaver') in P and not blocked15:
                P.add(('unite', x, 'ostrich'))
            # Rule 22 (blocked by Rule 3 for swan)
            if ('shout', x, 'peafowl') in P and not (blocked3 and x == 'swan'):
                P.add(('shout', x, 'beaver'))
            # Rule 5
            if lacks(('tear', x, 'badger')):
                P.add(('refuse', x, 'badger'))
            # Rule 8
            if ('create', x, 'dragon') in P:
                P.add(('refuse', x, 'dinosaur'))
            # Rule 12
            if lacks(('create', x, 'vampire')):
                P.add(('enjoy', x, 'ant'))
            # Rule 14
            if ('wants', x, 'fangtooth') in P:
                N.add(('shout', x, 'beetle'))
            # Rule 17
            if lacks(('refuse', x, 'dinosaur')):
                P.add(('reveal', x, 'zebra'))
            # Rule 18
            if lacks(('shout', x, 'beetle')) and ('reveal', x, 'zebra') in P:
                N.add(('trade', x, 'stork'))
            # Rule 19
            if ('refuse', x, 'badger') in P:
                P.add(('shout', x, 'dragonfly'))
            # Rule 20
            if ('shout', x, 'dragonfly') in P:
                P.add(('wants', x, 'fangtooth'))
            # Rule 4
            if lacks(('trade', 'bee', 'stork')) and ('trade', 'beetle', 'stork') in P:
                P.add(('wants', 'stork', 'goat'))

        if (frozenset(P), frozenset(N)) == snap:
            break

    # Positive conclusions override conflicting negative ones (preference order)
    N -= P
    if TARGET in P:
        return 'proved', P, N
    if TARGET in N:
        return 'disproved', P, N
    return 'unknown', P, N


cwa_verdict, P_cwa, N_cwa = run('cwa')
strict_verdict, _, _ = run('strict')

print("Closed-world run (negated antecedents read as failure-to-derive):", cwa_verdict)
print("  beetle trades with stork:", ('trade', 'beetle', 'stork') in P_cwa)
print("  swan shouts at peafowl:", ('shout', 'swan', 'peafowl') in P_cwa)
print("  stork wants to see the goat:", ('wants', 'stork', 'goat') in P_cwa)
print("Strict run (negations need explicit statement):", strict_verdict)

if cwa_verdict == SUBMITTED:
    print("CHECK PASS")
elif cwa_verdict == 'unknown':
    print("CHECK UNKNOWN")
else:
    print("CHECK FAIL")
