# Model the explanation: abstaining from out-of-season vegetables counts as
# a meaningful dietary choice only if the agent can choose between seasonal
# and out-of-season vegetables. Each candidate option is tested as a
# necessary assumption: the conclusion must fail when that option is false,
# with the other options left as they are.
options = {
    "A": "demanding",    # Confucius is very demanding about diet
    "B": "both_eras",    # Confucius lived when both kinds of vegetables existed
    "C": "can_choose",   # We can choose seasonal or out-of-season vegetables
}

def conclusion(w):
    # Abstention is a meaningful proposition only if choice is possible.
    return w["can_choose"]

worlds = []
for vals in product([False, True], repeat=3):
    w = {"demanding": vals[0], "both_eras": vals[1], "can_choose": vals[2]}
    worlds.append(w)

necessary = []
for key, name in options.items():
    # Worlds where all other options hold but this one fails.
    others = [n for k, n in options.items() if k != key]
    breaks = [
        w for w in worlds
        if all(w[o] for o in others) and not w[name] and not conclusion(w)
    ]
    # Necessary: whenever the conclusion holds, this option must hold.
    holds_whenever_concl = all(w[name] for w in worlds if conclusion(w))
    if holds_whenever_concl and breaks:
        necessary.append(key)

final = necessary[0] if len(necessary) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "worlds_checked": len(worlds),
        "necessary_options": necessary,
    },
}, separators=(",", ":")))
