from fractions import Fraction as F
from collections import Counter
import json


def poly_eval(pl, x):
    # pl is ordered low-to-high degree
    return sum(a * x ** i for i, a in enumerate(pl))


def divide_linear(pl, r):
    # Synthetic division of pl (low-to-high) by (x - r); returns quotient low-to-high
    hi = pl[::-1]
    out = [hi[0]]
    for a in hi[1:]:
        out.append(a + out[-1] * r)
    rem = out.pop()
    if rem != 0:
        raise ValueError("root check failed")
    return out[::-1]


def poly_mul_linear(pl, r):
    # Multiply pl (low-to-high) by (x - r)
    out = [F(0)] * (len(pl) + 1)
    for i, a in enumerate(pl):
        out[i + 1] += a
        out[i] += -r * a
    return out


def main():
    # c = 20/(-24) - (2 + -3)
    c = F(20, -24) - (F(2) + F(-3))

    # p(x) = (1/16)x^4 + 1 + (1/8)x^2 + 0*x - c*x^3
    p = {4: F(1, 16), 0: F(1), 2: F(1, 8), 1: F(0), 3: -c}

    # k(x) = p'(x): coefficient of x^(n-1) is n * a_n
    k = {}
    for n, a in p.items():
        if n > 0:
            k[n - 1] = k.get(n - 1, F(0)) + n * a

    deg = max(d for d, v in k.items() if v != 0)
    coeffs = [k.get(i, F(0)) for i in range(deg + 1)]  # low-to-high

    # Exhaustive rational root search over p/q, |p|<=60, 1<=q<=12
    candidates = sorted({F(num, den) for num in range(-60, 61) for den in range(1, 13)})

    poly = coeffs[:]
    roots = []
    while len(poly) > 1:
        found = None
        for r in candidates:
            if poly_eval(poly, r) == 0:
                found = r
                break
        if found is None:
            break
        roots.append(found)
        poly = divide_linear(poly, found)

    const = poly[0]  # remaining constant factor (leading coefficient)
    residual_degree = len(poly) - 1

    # Verify: const * prod(x - r) must equal k(x) exactly
    check = [const]
    for r in roots:
        check = poly_mul_linear(check, r)
    verified = (check == coeffs) and residual_degree == 0

    mult = Counter(roots)
    parts = []
    for r in sorted(mult):
        base = "s" if r == 0 else "(s - {})".format(r)
        m = mult[r]
        parts.append(base if m == 1 else "{}**{}".format(base, m))

    if verified:
        final_answer = "{}*{}".format(const, "*".join(parts))
    else:
        final_answer = "UNSUPPORTED"

    evidence = {
        "c": str(c),
        "k_coefficients_low_to_high": [str(x) for x in coeffs],
        "roots": [str(r) for r in roots],
        "root_multiplicities": {str(r): m for r, m in mult.items()},
        "leading_constant": str(const),
        "residual_degree": residual_degree,
        "verified_by_expansion": verified,
    }

    print(json.dumps({"final_answer": final_answer, "evidence": evidence}))


if __name__ == "__main__":
    main()
