from fractions import Fraction as F

def poly_mul(a, b):
    out = {}
    for p, x in a.items():
        for q, y in b.items():
            out[p + q] = out.get(p + q, F(0)) + x * y
    return {p: v for p, v in out.items() if v != 0}

def poly_eval(a, t):
    return sum(v * t**p for p, v in a.items())

def same_poly(a, b):
    keys = set(a) | set(b)
    return all(a.get(p, F(0)) == b.get(p, F(0)) for p in keys)

# Step 1: exact c
c = F(20, -24) - (2 + -3)
print("c =", c)

# Step 2: f(x) = (1/16)x^4 + 1 + (1/8)x^2 + 0x - c*x^3, as {power: coef}
f = {4: F(1, 16), 0: F(1), 2: F(1, 8), 1: F(0), 3: -c}

# Step 3: exact derivative k(x) = f'(x)
k = {}
for p, a in f.items():
    if p > 0 and a != 0:
        k[p - 1] = k.get(p - 1, F(0)) + a * p
k = {p: v for p, v in k.items() if v != 0}
print("k(x) coefficients (power: coef):", dict(sorted(k.items(), reverse=True)))

# Step 4: candidate factored form (1/4)*x*(x-1)^2, expanded exactly
candidate_factored = poly_mul({1: F(1, 4)}, poly_mul({1: F(1), 0: F(-1)}, {1: F(1), 0: F(-1)}))
print("Factored form expands to:", dict(sorted(candidate_factored.items(), reverse=True)))
print("Factored form equals k(x) exactly:", same_poly(candidate_factored, k))

# Step 5: submitted answer (1/4)x^3 + (57/24)x^2 + (1/4)x
submitted = {3: F(1, 4), 2: F(57, 24), 1: F(1, 4)}
print("Submitted coefficients:", dict(sorted(submitted.items(), reverse=True)))
print("Submitted equals k(x) exactly:", same_poly(submitted, k))

# Step 6: exact point checks
for t in [F(0), F(1), F(2), F(-1)]:
    print(f"x={t}: k={poly_eval(k, t)}, submitted={poly_eval(submitted, t)}")

if same_poly(submitted, k) and same_poly(candidate_factored, k):
    print("CHECK PASS")
else:
    print("CHECK FAIL")
